/**
 * Auto-Pull-to-Caster + conditional lightning damage (edge-distance aware)
 * - 修正：以 token 矩形边缘最短距离判断是否 <= 5 ft（而非中心距）
 * - 其余行为同之前：使用 MidiQOL.moveTokenFromPoint (优先)，动画后微调 snap，无动画微调
 */

(async () => {
  const DEFAULT_FEET = 15;      // 默认拉近距离（英尺）
  const AOE_TRIGGER_FEET = 5;   // 触发闪电伤害阈值（英尺）
  const SNAP_TWEAK_DELAY = 300; // 等待动画完成的毫秒数

  const gs = canvas.grid.size;
  const feetPerSquare = canvas.scene.grid?.distance ?? 5;
  const S = CONST.GRID_SNAPPING_MODES;

  function pxFromFeet(feet) { return (feet / feetPerSquare) * gs; }
  function getCanvasTokenCenter(tok) { return { x: tok.center?.x ?? (tok.x + tok.w/2), y: tok.center?.y ?? (tok.y + tok.h/2) }; }
  function getTokenGridSize(tok) { return { w: Math.max(1, Math.floor(Number(tok.document?.width ?? tok.document?._source?.width ?? 1))), h: Math.max(1, Math.floor(Number(tok.document?.height ?? tok.document?._source?.height ?? 1))) }; }

  // parity snapping: odd -> cell center, even -> intersection
  function computeSnappedCenterForToken(rawPoint, tokenGridW, tokenGridH) {
    let cell;
    try { cell = canvas.grid.getSnappedPoint({ x: rawPoint.x, y: rawPoint.y }, { mode: S.CENTER, resolution: 1 }); }
    catch (e) { cell = { x: Math.round(rawPoint.x / gs) * gs, y: Math.round(rawPoint.y / gs) * gs }; }
    const snapX = (tokenGridW % 2 === 1) ? cell.x : Math.round(rawPoint.x / gs) * gs;
    const snapY = (tokenGridH % 2 === 1) ? cell.y : Math.round(rawPoint.y / gs) * gs;
    const col = Math.floor(snapX / gs), row = Math.floor(snapY / gs);
    const topLeftCol = col - Math.floor(tokenGridW / 2);
    const topLeftRow = row - Math.floor(tokenGridH / 2);
    const centerX = Math.round((topLeftCol + tokenGridW/2) * gs);
    const centerY = Math.round((topLeftRow + tokenGridH/2) * gs);
    const topLeftX = Math.round(topLeftCol * gs);
    const topLeftY = Math.round(topLeftRow * gs);
    return { center: { x: centerX, y: centerY }, topLeft: { x: topLeftX, y: topLeftY } };
  }

  // rectangle edge distance in pixels between two tokens (0 if touching/overlapping)
  function pixelEdgeDistanceBetweenTokens(a, b) {
    // rectA: left, right, top, bottom
    const aLeft = a.x;
    const aRight = a.x + a.w;
    const aTop = a.y;
    const aBottom = a.y + a.h;
    const bLeft = b.x;
    const bRight = b.x + b.w;
    const bTop = b.y;
    const bBottom = b.y + b.h;

    // horizontal separation
    const dx = Math.max(0, Math.max(bLeft - aRight, aLeft - bRight));
    const dy = Math.max(0, Math.max(bTop - aBottom, aTop - bBottom));
    // if overlapping in one axis dx or dy is 0
    return Math.hypot(dx, dy);
  }

  // feet distance based on edge-to-edge (rectangles)
  function feetEdgeDistanceBetweenTokens(tokA, tokB) {
    const px = pixelEdgeDistanceBetweenTokens(tokA, tokB);
    return (px / gs) * feetPerSquare;
  }

  // get caster (你控制的 token 优先)
  const casterToken = canvas.tokens.controlled[0] ?? token ?? null;
  if (!casterToken) {
    return ui.notifications.warn("请先控制（选择）施法者的 token，然后再执行宏（此宏以施法者为圆心）。");
  }
  const casterCenter = getCanvasTokenCenter(casterToken);

  // get targets: 优先 game.user.targets，否则用被控 tokens（排除施法者）
  let targets = Array.from(game.user.targets ?? []);
  if (targets.length === 0) targets = canvas.tokens.controlled.filter(t => t.id !== casterToken.id);
  if (!targets || targets.length === 0) {
    return ui.notifications.warn("未检测到目标（请 target 好目标或控制目标 token）");
  }

  // helper: get caster level
  function getActorLevel(actor) {
    try {
      const lv = actor.system?.details?.level ?? actor.system?.level ?? actor.data?.data?.details?.level ?? null;
      if (lv) return Number(lv);
    } catch {}
    try {
      const cls = actor.items?.filter(i => i.type === "class") ?? [];
      let s = 0;
      for (const c of cls) s += Number(c.system?.levels ?? c.system?.level ?? 0);
      if (s > 0) return s;
    } catch {}
    return 1;
  }
  function damageDiceCountForLevel(level) {
    let n = 1;
    if (level >= 5) n = 2;
    if (level >= 11) n = 3;
    if (level >= 17) n = 4;
    return n;
  }

  // apply lightning damage via MidiQOL.DamageOnlyWorkflow (safe minimal itemData)
  async function applyLightningDamage(casterActor, casterTok, targetTok, diceCount) {
    try {
      const formula = `${diceCount}d8[lightning]`;
      const roll = await new Roll(formula).roll({ async: true });
      await roll.toMessage({ flavor: `闪电伤害（拉近触发）` });

      const safeItemData = { name: "Forced Pull Lightning", type: "spell", system: {}, flags: {}, effects: [] };
      await new MidiQOL.DamageOnlyWorkflow(
        casterActor ?? targetTok.actor,
        casterTok ?? undefined,
        Number(roll.total),
        "lightning",
        [targetTok],
        roll,
        {
          flavor: `拉近触发的闪电伤害`,
          itemCardUuid: null,
          itemData: safeItemData,
          useOther: false
        }
      );
      return true;
    } catch (e) {
      console.error("applyLightningDamage failed", e);
      ChatMessage.create({ content: `${targetTok.name} 应受到 闪电伤害，但自动应用失败：${e?.message ?? e}` });
      return false;
    }
  }

  // ---------- 主流程 ----------
  const casterActor = casterToken.actor;
  const casterLevel = getActorLevel(casterActor);

  for (const tk of targets) {
    try {
      // compute edge distance (feet) from tk to caster BEFORE move — used to cap 'toward' movement
      const preEdgeFeet = feetEdgeDistanceBetweenTokens(tk, casterToken);
      // desired move amount in pixels
      const desiredPixels = pxFromFeet(DEFAULT_FEET);
      // For 'pull' we pass negative distance to moveTokenFromPoint
      const moveArg = -Math.abs(DEFAULT_FEET);

      // If moving toward (pull), cap so as not to move past caster edge: effectivePixels = min(desired, preEdgePx)
      // convert preEdgeFeet to pixels:
      const preEdgePx = (preEdgeFeet / feetPerSquare) * gs;
      let effectivePixels = desiredPixels;
      if (preEdgePx <= 0) {
        effectivePixels = 0;
      } else {
        effectivePixels = Math.min(desiredPixels, Math.max(0, preEdgePx - 1)); // -1px slack
      }

      // If effectivePixels <= 0, skip movement (already touching)
      if (effectivePixels <= 0) {
        ChatMessage.create({ content: `${tk.name} 已在施法者边缘附近，未移动。` });
        // Still check trigger since already touching -> should trigger damage
        const finalEdgeFeet = feetEdgeDistanceBetweenTokens(tk, casterToken);
        if (finalEdgeFeet <= AOE_TRIGGER_FEET + 1e-6) {
          const diceCount = damageDiceCountForLevel(casterLevel);
          await applyLightningDamage(casterActor, casterToken, tk, diceCount);
          ChatMessage.create({ content: `${tk.name} 在初始位置与施法者边缘距离 ${finalEdgeFeet.toFixed(2)}ft，触发 ${diceCount}d8 闪电伤害` });
        }
        continue;
      }

      // Try moveTokenFromPoint (animated)
      if (typeof MidiQOL?.moveTokenFromPoint === "function") {
        try {
          // Note: moveTokenFromPoint expects distance in feet (grid units). For pull we pass negative.
          await MidiQOL.moveTokenFromPoint(tk, moveArg, casterCenter);
        } catch (e) {
          console.warn("moveTokenFromPoint failed, fallback to moveToken animation", e);
          // fallback: animate via moveToken to a raw point computed along vector
          const cur = getCanvasTokenCenter(tk);
          let vx = casterCenter.x - cur.x; let vy = casterCenter.y - cur.y;
          if (Math.hypot(vx, vy) < 1e-6) { vx = 1; vy = 0; }
          const norm = Math.hypot(vx, vy);
          const rawTarget = { x: Math.round(cur.x + (vx / norm) * effectivePixels), y: Math.round(cur.y + (vy / norm) * effectivePixels) };
          await MidiQOL.moveToken(tk, rawTarget, true);
        }
      } else if (typeof MidiQOL?.moveToken === "function") {
        // fallback animate via moveToken
        const cur = getCanvasTokenCenter(tk);
        let vx = casterCenter.x - cur.x; let vy = casterCenter.y - cur.y;
        if (Math.hypot(vx, vy) < 1e-6) { vx = 1; vy = 0; }
        const norm = Math.hypot(vx, vy);
        const rawTarget = { x: Math.round(cur.x + (vx / norm) * effectivePixels), y: Math.round(cur.y + (vy / norm) * effectivePixels) };
        await MidiQOL.moveToken(tk, rawTarget, true);
      } else {
        ui.notifications.error("无法找到 MidiQOL.moveTokenFromPoint 或 MidiQOL.moveToken，传送无法执行。");
        continue;
      }

      // wait for animation to settle
      await new Promise(r => setTimeout(r, SNAP_TWEAK_DELAY));

      // micro-snap to ensure grid alignment (no animation)
      const { w: tgW, h: tgH } = getTokenGridSize(tk);
      const curCenterAfter = getCanvasTokenCenter(tk);
      const snapped = computeSnappedCenterForToken(curCenterAfter, tgW, tgH);
      if (Math.abs(curCenterAfter.x - snapped.center.x) > 1 || Math.abs(curCenterAfter.y - snapped.center.y) > 1) {
        try { await MidiQOL.moveToken(tk, { x: snapped.center.x, y: snapped.center.y }, false); } catch(e) { console.warn("snap tweak failed", e); }
      }

      // now measure edge-to-edge feet after movement
      const finalEdgeFeet = feetEdgeDistanceBetweenTokens(tk, casterToken);

      // If within threshold -> apply lightning damage
      if (finalEdgeFeet <= AOE_TRIGGER_FEET + 1e-6) {
        const diceCount = damageDiceCountForLevel(casterLevel);
        await applyLightningDamage(casterActor, casterToken, tk, diceCount);
        ChatMessage.create({ content: `${tk.name} 在被拉近后与施法者边缘距离 ${finalEdgeFeet.toFixed(2)} 英尺，受到 ${diceCount}d8 闪电伤害（等级 ${casterLevel}）` });
      } else {
        ChatMessage.create({ content: `${tk.name} 拉近后与施法者边缘距离 ${finalEdgeFeet.toFixed(2)} 英尺，未触发闪电伤害` });
      }

    } catch (err) {
      console.error("Auto-pull+damage (edge-aware) failed for target", tk, err);
      ChatMessage.create({ content: `${tk.name} 的拉近或伤害过程出错（查看控制台）` });
    }
  } // for targets

  console.log("Auto-pull+lightning (edge-aware) finished");
})();
